    # Find the repeated motif region, then mark its continuation in color 1.
    # The motif is a multi-row texture; extrapolate its periodic columns into
    # the trailing blank/background area of each participating row.
    bg=max(set(v for row in grid for v in row), key=lambda v:sum(row.count(v) for row in grid))
    for r in range(h):
